UPDATE children SET
  enrollment_number = (SELECT enrollment_number FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  spc = (SELECT spc FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  birth_date = (SELECT birth_date FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  gender = (SELECT gender FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  address_hamlet = (SELECT address_hamlet FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  address_commune = (SELECT address_commune FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  address_province = (SELECT address_province FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  father_name = (SELECT father_name FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  father_job = (SELECT father_job FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  father_workplace = (SELECT father_workplace FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  mother_name = (SELECT mother_name FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  mother_job = (SELECT mother_job FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  mother_workplace = (SELECT mother_workplace FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  phone = (SELECT phone FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name),
  zalo_phone = CASE WHEN zalo_phone = '' THEN (SELECT phone FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name) ELSE zalo_phone END,
  class_name = 'Mầm 3',
  class_id = COALESCE((SELECT id FROM classes WHERE classes.school_id = children.school_id AND classes.name = 'Mầm 3' LIMIT 1), class_id)
WHERE school_id = (SELECT id FROM schools WHERE name LIKE '%Ban Mai%' LIMIT 1)
  AND EXISTS (SELECT 1 FROM `_syll_import_0016` WHERE `_syll_import_0016`.name = children.name);
