INSERT INTO children (
  school_id, name, class_name, class_id, birth_date, enrollment_number, spc, gender,
  address_hamlet, address_commune, address_province, guardian, phone, allergy, status,
  father_name, father_job, father_workplace, mother_name, mother_job, mother_workplace, zalo_phone
)
SELECT
  schools.id, s.name, 'Mầm 3',
  (SELECT id FROM classes WHERE classes.school_id = schools.id AND classes.name = 'Mầm 3' LIMIT 1),
  s.birth_date, s.enrollment_number, s.spc, s.gender, s.address_hamlet, s.address_commune,
  s.address_province, '', s.phone, 'Không', 'Đang học', s.father_name, s.father_job,
  s.father_workplace, s.mother_name, s.mother_job, s.mother_workplace, s.phone
FROM `_syll_import_0016` s
JOIN schools ON schools.id = (SELECT id FROM schools WHERE name LIKE '%Ban Mai%' LIMIT 1)
WHERE NOT EXISTS (
  SELECT 1 FROM children WHERE children.school_id = schools.id AND children.name = s.name
);
